cd /home/user/guidebook; python3 - <<'EOF'
import sqlite3,yaml
sm=yaml.safe_load(open('governance/stage-map.yaml'))['tables']
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
for t,st in sorted(sm.items()):
    if st!='base': continue
    try: fks=c.execute(f'pragma foreign_key_list("{t}")').fetchall()
    except Exception as e: print(t,'ERR',e); continue
    cols={r[1]:r for r in c.execute(f'pragma table_info("{t}")')}
    for f in fks:
        if sm.get(f[2])!='base':
            print(t, f[3],'->',f[2],sm.get(f[2]),'notnull' if cols[f[3]][3] else 'nullable', c.execute(f'select count(*) from "{t}" where "{f[3]}" is not null').fetchone()[0])
print(sm.get('observed_terms'), sm.get('search_execution_forms'), sm.get('term_adjudications'))
EOF
